declare(strict_types=1);require __DIR__.'/bootstrap.php';installSchema();$writer=new \LittyWatch\Market\StructuredOfferWriter(db(),parserV2());$rows=db()->query('SELECT id,message FROM messages ORDER BY id')->fetchAll();$created=0;foreach($rows as $row)$created+=$writer->parseMessage((int)$row['id'],(string)$row['message'],true);header('Content-Type: application/json; charset=utf-8');echo json_encode(['parser_version'=>'v2.1','messages_reparsed'=>count($rows),'structured_offers_created'=>$created,'legacy_offers_untouched'=>true,'review_url'=>'/structured-offers'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
